?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Partidas en vivo | YUGIOH MD</title><link rel="stylesheet" href="./assets/app.css?v=20260922-intelligence-5"><style>body{margin:0;background:#050d19;color:#eef5ff;font-family:Inter,Arial,sans-serif}.public-live{max-width:1500px;margin:auto;padding:clamp(16px,3vw,42px)}.public-live header{display:flex;justify-content:space-between;align-items:center;gap:18px;border-bottom:1px solid #1b4264;padding-bottom:20px}.public-live h1{font-size:clamp(28px,5vw,56px);margin:0}.public-live header span{color:#ffd25f;font-weight:800}.public-live-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:16px;margin-top:24px}.public-match{border:1px solid #244663;background:#09172a;padding:20px;border-radius:8px}.public-match.is-live{border-color:#20c997;box-shadow:0 0 0 1px #20c99755}.public-match .meta{display:flex;justify-content:space-between;color:#9db0ce}.public-match .teams{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin:24px 0}.public-match .teams b{font-size:clamp(18px,3vw,28px)}.public-match .teams b:last-child{text-align:right}.public-match .score{font-size:32px;color:#ffd25f;font-weight:900}.public-empty{padding:50px;border:1px dashed #35506f;text-align:center;margin-top:24px;color:#aabbd5}@media(max-width:600px){.public-live header{align-items:flex-start;flex-direction:column}.public-match .teams{grid-template-columns:1fr}.public-match .teams b:last-child{text-align:left}.public-match .score{font-size:26px}}</style></head><body><main class="public-live"><header><div><span>YUGIOH MD | STATION X TULUA</span><h1>Centro público de partidas</h1><p>Mesas activas y próximas partidas. Actualización automática.</p></div><a class="btn btn-outline-info" href="./?public_season=<?php echo $publicSeasonId; ?>#estadisticas">Ver temporada</a></header><section class="public-live-grid" id="public-live-grid"></section></main><script>const grid=document.getElementById('public-live-grid');const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function refresh(){try{const r=await fetch('./?api=live',{cache:'no-store'});const d=await r.json();const rows=(d.matches||[]).filter(m=>!['FINALIZADA','COMPLETED'].includes(String(m.estado||'').toUpperCase())).sort((a,b)=>String(a.scheduled_on+' '+a.starts_at).localeCompare(String(b.scheduled_on+' '+b.starts_at)));grid.innerHTML=rows.length?rows.map(m=>`<article class="public-match ${String(m.estado).toUpperCase().includes('CURSO')?'is-live':''}"><div class="meta"><span>${esc(m.competition_name||'Partida')}</span><b>R${esc(m.ronda||'-')} | Mesa ${esc(m.mesa||'-')}</b></div><div class="teams"><b>${esc(m.a||'Deck A')}<small>${esc(m.team_a||'')}</small></b><span class="score">${esc(m.score||'VS')}</span><b>${esc(m.b||'Deck B')}<small>${esc(m.team_b||'')}</small></b></div><div class="meta"><span>${esc(m.scheduled_on||'Sin fecha')} ${esc(String(m.starts_at||'').slice(0,5))}</span><strong>${esc(m.estado||'PENDIENTE')}</strong></div></article>`).join(''):'<div class="public-empty">No hay mesas activas o próximas en este momento.</div>'}catch(e){grid.innerHTML='<div class="public-empty">No se pudo actualizar el marcador. Se reintentará automáticamente.</div>'}}refresh();setInterval(refresh,<?php echo $refreshSeconds * 1000; ?>);</script><?php echo ygo_ui_labels_script($presentationLabels); ?></body></html><?php
